<div class="grid gap-6" x-data="{ bank: @js((string) $selectedBankId), unit: @js((string) $selectedUnitId), cases: @js($caseOptions), banks: @js($banks->map(fn ($bank) => ['id' => $bank->id, 'units' => $bank->units->map(fn ($unit) => ['id' => $unit->id, 'name' => $unit->name])->values()])->values()), caseId: @js((string) $selectedCaseId), get selectedCase() { return this.cases.find(item => String(item.id) === String(this.caseId)); }, get units() { return this.banks.find(item => String(item.id) === String(this.bank))?.units || []; } }">
    <section class="rounded-xl border border-gray-200 bg-white p-6 shadow-sm"><h2 class="text-lg font-bold">Data Konsumen</h2>@if(!$biChecking)<div class="mt-5"><x-input-label for="sales_case_id" value="Konsumen / kavling"/><select id="sales_case_id" name="sales_case_id" x-model="caseId" class="mt-1 block w-full rounded-md border-gray-300" required><option value="">Pilih data konsumen</option>@foreach($caseOptions as $case)<option value="{{ $case['id'] }}">{{ $case['label'] }}</option>@endforeach</select><x-input-error class="mt-2" :messages="$errors->get('sales_case_id')"/></div>@else<div class="mt-5 rounded-lg bg-gray-50 p-4"><p class="font-semibold">{{ $biChecking->salesCase->consumer->nama_konsumen }} — {{ $biChecking->salesCase->lot->project->name }}-{{ $biChecking->salesCase->lot->code }}</p><p class="mt-1 text-xs text-gray-500">NIK {{ $biChecking->salesCase->consumer->no_ktp }}</p></div>@endif<div class="mt-5 grid gap-4 sm:grid-cols-3" x-show="selectedCase"><div><p class="text-xs font-bold uppercase text-gray-500">Kavling</p><p class="mt-1 font-semibold" x-text="selectedCase?.lot"></p></div><div><p class="text-xs font-bold uppercase text-gray-500">NIK</p><p class="mt-1 font-semibold" x-text="selectedCase?.nik"></p></div><div><p class="text-xs font-bold uppercase text-gray-500">Pembayaran</p><p class="mt-1 font-semibold" x-text="selectedCase?.payment"></p></div></div></section>
    <section class="rounded-xl border border-gray-200 bg-white p-6 shadow-sm"><h2 class="text-lg font-bold">Hasil BI Checking</h2><div class="mt-5 grid gap-5 md:grid-cols-2"><div><x-input-label for="bank_id" value="Bank"/><select id="bank_id" name="bank_id" x-model="bank" @change="unit = ''" class="mt-1 block w-full rounded-md border-gray-300" required><option value="">Pilih bank</option>@foreach($banks as $item)<option value="{{ $item->id }}">{{ $item->name }}</option>@endforeach</select><x-input-error class="mt-2" :messages="$errors->get('bank_id')"/></div><div><x-input-label for="bank_unit_id" value="KC/Unit"/><select id="bank_unit_id" name="bank_unit_id" x-model="unit" class="mt-1 block w-full rounded-md border-gray-300" required><option value="">Pilih KC/Unit</option><template x-for="item in units" :key="item.id"><option :value="item.id" x-text="item.name"></option></template></select><x-input-error class="mt-2" :messages="$errors->get('bank_unit_id')"/></div><div><x-input-label for="checking_date" value="Tanggal BI Checking"/><x-text-input id="checking_date" name="checking_date" type="date" class="mt-1 block w-full" :value="old('checking_date', $biChecking?->checking_date?->format('Y-m-d') ?? today()->format('Y-m-d'))" required/></div><div><x-input-label for="slik_result" value="Hasil BI SLIK"/><select id="slik_result" name="slik_result" class="mt-1 block w-full rounded-md border-gray-300" required>@foreach(['OK','KOL 1','KOL 2','KOL 3','KOL 4','KOL 5'] as $option)<option value="{{ $option }}" @selected(old('slik_result', $biChecking?->slik_result) === $option)>{{ $option }}</option>@endforeach</select></div><div class="md:col-span-2"><x-input-label for="notes" value="Keterangan"/><textarea id="notes" name="notes" rows="5" class="mt-1 block w-full rounded-md border-gray-300">{{ old('notes', $biChecking?->notes) }}</textarea></div><div><x-input-label for="bank_decision" value="Putusan Bank"/><select id="bank_decision" name="bank_decision" class="mt-1 block w-full rounded-md border-gray-300" required><option value="Lanjut" @selected(old('bank_decision', $biChecking?->bank_decision) === 'Lanjut')>Lanjut</option><option value="Reject" @selected(old('bank_decision', $biChecking?->bank_decision) === 'Reject')>Reject</option></select></div></div></section>
</div>
